import{_ as a,o as l,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph User + Dev Monthly - August 2026","description":"","frontmatter":{"title":"Ceph User + Dev Monthly - August 2026","date":"2026-08-20T00:00:00.000Z","updated":"2026-08-20T00:00:00.000Z","tags":["会议纪要","RGW","BlueStore","OSD","Cephadm"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_User_+_Dev_Monthly_-_August_2026.md","filePath":"posts/2026/Ceph_User_+_Dev_Monthly_-_August_2026.md","lastUpdated":null}'),t={name:"posts/2026/Ceph_User_+_Dev_Monthly_-_August_2026.md"};function i(n,e,p,s,d,c){return l(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次 Ceph User + Dev Monthly 会议于 2026 年 8 月召开，涵盖五个主要议题：upmap 条目进度追踪、RGW dynamic resharding 与版本桶的交互问题、操作系统支持计划、BlueStore 慢操作警告灵敏度调整，以及通过 Cephadm 管理 HAProxy SSL 配置。</p><h2 id="议题一-upmap-条目进度追踪" tabindex="-1">议题一：upmap 条目进度追踪 <a class="header-anchor" href="#议题一-upmap-条目进度追踪" aria-label="Permalink to &quot;议题一：upmap 条目进度追踪&quot;">​</a></h2><p><strong>背景</strong>：用户 Joel 在向集群新增大量 OSD 后，使用 upmap remap 脚本（关闭 balancer 状态下）创建了 upmap 条目，再重新开启 balancer 进行数据迁移。问题在于无法区分哪些 upmap 条目是 balancer 模块自行生成的、哪些是脚本手动创建的，导致难以判断数据迁移是否已完成。</p><p><strong>讨论要点</strong>：</p><ul><li>balancer 模块本身不区分自动生成与手动创建的 upmap 条目；开启 balancer 后，它可能保留或替换任何已有条目</li><li>从纯 OSD 数量角度看，Joel 将 OSD 数量翻倍后，upmap 条目数量也大致翻倍（约 97 → 236），符合预期</li></ul><p><strong>解决方案</strong>：Alexander 推荐使用 <strong>OSD map offline optimization 工具</strong>进行 dry run：</p><ul><li>提供 <code>--upmap-deviation</code>（与集群配置一致）和 <code>--upmap-active</code> 两个参数</li><li>加上 <code>--upmap-active</code> 后，工具会循环运行直到无剩余工作，模拟 balancer 未来所有步骤</li><li>输出文件中的行数即代表剩余工作量；行数为零表示迁移完成</li><li>另可使用 <code>upmap cleanup</code> flag 查看 balancer 会移除哪些无效 upmap 条目</li></ul><p><strong>待办</strong>：</p><ul><li>Joel 参考 Alexander 分享的文档链接，尝试 offline optimization 工具</li><li>提醒：<code>upmap cleanup</code> 仅统计移除操作，不包含新增操作，需综合评估总工作量</li></ul><h2 id="议题二-rgw-dynamic-resharding-与版本桶" tabindex="-1">议题二：RGW Dynamic Resharding 与版本桶 <a class="header-anchor" href="#议题二-rgw-dynamic-resharding-与版本桶" aria-label="Permalink to &quot;议题二：RGW Dynamic Resharding 与版本桶&quot;">​</a></h2><p><strong>背景</strong>：Joel 观察到，在版本桶（versioned bucket）fill status 正常的情况下，仍频繁触发 large OMAP object 警告（数百次）。疑问在于 dynamic resharding 的触发逻辑是否基于各 shard 的平均值，而非单个 shard 的实际键数。</p><p><strong>讨论要点</strong>：</p><ul><li><code>bucket limit check</code> 和 <code>bucket stats</code> 均基于各 shard 统计数据的汇总平均值，而非最大值；这对于非版本桶来说通常问题不大，因为键在各 shard 间分布较均匀</li><li>版本桶的特殊性：同一对象名的所有版本必须存储在同一 shard（保证原子更新和版本一致性），导致 shard 间数据分布不均</li><li>版本桶的 OMAP 键结构：每个对象名对应约 3 条索引键（plain 条目、instance 条目、<code>\\x80</code> OH 条目），因此即便每个对象只有一个版本，键数也会是对象数的约 3 倍</li><li>自 <strong>Squid</strong> 版本起，resharding 在计算版本桶阈值时已将键数乘以 3 进行补偿（hardcoded），以避免过度 resharding</li></ul><p><strong>Casey 的判断</strong>：</p><ul><li>非版本桶在正常情况下 resharding 逻辑应能正常工作</li><li>版本桶出现 large OMAP 警告，通常是因为<strong>同一对象名存在大量版本</strong>，导致单个 shard 键数远超均值</li><li>建议方案：通过 lifecycle policy 限制每个对象名的非当前版本数量；large OMAP 警告本身可作为运维人员识别问题桶的有效信号</li></ul><p><strong>版本信息</strong>：Joel 的集群为 Ceph 18（Reef）版本；Casey 表示版本桶三倍系数的修复在 Squid 中可见，Reef 中不确定是否已 backport。</p><p><strong>待办</strong>：</p><ul><li>Joel 确认当前查看 shard 键数的具体命令（bi list 等）</li><li>如需要，可通过 <code>rados listomapkeys</code> 查看单个 index object 的键数</li></ul><h2 id="议题三-操作系统支持与版本规划" tabindex="-1">议题三：操作系统支持与版本规划 <a class="header-anchor" href="#议题三-操作系统支持与版本规划" aria-label="Permalink to &quot;议题三：操作系统支持与版本规划&quot;">​</a></h2><p><strong>背景</strong>：Joel 希望了解 Ceph 各版本在不同 OS 上的测试覆盖情况，以便规划基础设施的长期维护策略。</p><p><strong>讨论要点</strong>：</p><ul><li>Ubuntu 24.04 已在 <strong>Tentacle</strong>（即将发布）中获得支持，并将 backport 至当前版本</li><li>Ubuntu 26.04 目标支持版本为下一个代号 <strong>Vampire</strong></li><li>目前仍依赖 Ubuntu 22.04（LTS）的原因：24.04 支持工作进展较晚，导致维护窗口出现重叠</li><li>Ceph 的通用原则：尽量在 OS EOL 前后同时支持两个主要 OS 版本，保障用户升级路径</li><li>Ceph 客户端库的版本兼容性：通常客户端可跨两个主要 Ceph 版本与服务端通信，旧版客户端包应仍可用</li></ul><p><strong>关联问题（Gregory 提出）</strong>：</p><ul><li>在 Cephadm 容器化部署环境下，<code>ceph-volume</code> 包会作为依赖引入 <code>ceph-common</code>，进而引入 <code>libqt</code></li><li><code>libqt</code> 在 Ubuntu 22.04 上不属于 main 仓库，需要 Ubuntu Pro 才有安全更新支持</li><li>安全团队已通报该依赖存在漏洞；Debian 对应包无此依赖</li><li>短期 workaround：卸载主机上的相关包，通过 <code>cephadm shell</code> 调用工具（性能开销较大）</li></ul><p><strong>后续行动</strong>：</p><ul><li>Gregory 可在 Ceph tracker 中开 issue 跟进 <code>libqt</code> 依赖问题，由社区进一步调查</li><li>注意：此问题当前确认于 Squid 版本；Squid 即将 EOL，Tentacle 中情况未知</li></ul><h2 id="议题四-bluestore-慢操作警告灵敏度" tabindex="-1">议题四：BlueStore 慢操作警告灵敏度 <a class="header-anchor" href="#议题四-bluestore-慢操作警告灵敏度" aria-label="Permalink to &quot;议题四：BlueStore 慢操作警告灵敏度&quot;">​</a></h2><p><strong>背景</strong>：Gregory 反映客户频繁收到 BlueStore 慢操作（slow operations）警告，该警告在单次操作超过 5 秒时触发，且持续 24 小时，导致客户误以为集群存在严重问题。</p><p><strong>讨论要点</strong>：</p><ul><li>当前默认阈值（5 秒）的设计意图：磁盘早期故障征兆往往表现为偶发性慢操作，因此希望尽早捕获</li><li>实际运维经验表明：随着阈值从 5 秒提升到 10 秒乃至更高，真正发生磁盘故障的概率确实接近 100%——说明该指标具有预测价值</li><li>争议点：单次操作超时即触发集群级 <code>HEALTH_WARN</code> 状态，信噪比过低；若磁盘真有问题，通常会有大量操作超时，而非仅一次</li><li>建议：调整默认配置（BlueStore 相关参数），或至少重新评估该阈值是否合理</li></ul><p><strong>后续行动</strong>：</p><ul><li>Gregory 在 BlueStore 项目下提交 tracker，由 Adam Kupoop（BlueStore 维护者）评估是否调整默认值</li></ul><h2 id="议题五-通过-cephadm-配置-haproxy-ssl-cipher" tabindex="-1">议题五：通过 Cephadm 配置 HAProxy SSL Cipher <a class="header-anchor" href="#议题五-通过-cephadm-配置-haproxy-ssl-cipher" aria-label="Permalink to &quot;议题五：通过 Cephadm 配置 HAProxy SSL Cipher&quot;">​</a></h2><p><strong>背景</strong>：Gregory 的集群使用 Cephadm 部署了 RGW，自动生成 HAProxy 配置。安全团队要求禁用 SSL 端点上的若干弱 cipher，但直接修改 <code>haproxy.cfg</code> 属于非标准操作方式，且不易维护。</p><p><strong>讨论要点</strong>：</p><ul><li>标准做法（已知）：替换 <code>haproxy.cfg.j2</code> Jinja2 模板，但这等同于完全接管该配置文件</li><li>Gregory 希望寻找更轻量的方式，可能通过 Cephadm 的 spec 文件机制进行局部覆盖</li><li>目前无人在会上能给出明确答案</li></ul><p><strong>后续行动</strong>：</p><ul><li>在 Slack <code>#cephadm</code> 频道提问，寻求有相关经验的社区成员协助</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次会议主要围绕 Ceph 运维中的实际问题展开，涉及 balancer/upmap 调试方法、RGW 版本桶 resharding 边界情况、OS 版本支持路线图、BlueStore 告警优化以及 Cephadm 配置灵活性等多个方向。大部分问题都有了明确的排查路径或 tracker 跟进计划。下次会议将于下月召开。</p>',41)])])}const g=a(t,[["render",i]]);export{h as __pageData,g as default};
